alter table public.zoom_profiles add constraint zoom_avatar_id check (avatar_id is null or avatar_id ~ '^avatar_(00[1-9]|0[1-9][0-9]|1[0-7][0-9]|18[0-7])$');
create table public.zoom_usage_events (id bigint generated always as identity primary key, user_id uuid not null references public.zoom_profiles(id) on delete cascade, session_id uuid not null, event_type text not null check(event_type ~ '^[a-z_]{2,64}$'), route_id text check(route_id ~ '^[a-z0-9_/-]{1,120}$'), process_id text check(process_id ~ '^[a-z0-9_/-]{1,120}$'), category_id text check(category_id ~ '^[a-z0-9_/-]{1,120}$'), tool_id text check(tool_id ~ '^[a-z0-9_/-]{1,120}$'), created_at timestamptz not null default now());
create table public.zoom_usage_sessions (session_id uuid primary key, user_id uuid not null references public.zoom_profiles(id) on delete cascade, started_at timestamptz not null default now(), ended_at timestamptz, active_seconds integer not null default 0 check(active_seconds >= 0), last_interaction timestamptz);
create table public.zoom_presence (user_id uuid primary key references public.zoom_profiles(id) on delete cascade, session_id uuid not null, state text not null check(state in ('active','idle','offline')), last_heartbeat timestamptz not null default now(), last_interaction timestamptz);
create table public.zoom_feedback_reports (id uuid primary key default gen_random_uuid(), reporter_user_id uuid not null references public.zoom_profiles(id) on delete cascade, type text not null check(type in ('missing_information','incorrect_outdated','not_working','ui_ux','change_suggestion')), status text not null default 'new' check(status in ('new','reviewing','planned','resolved','closed','dismissed')), route_id text, process_id text, category_id text, page_label text, what_noticed text not null check(char_length(what_noticed) <= 4000), suggested_change text check(char_length(suggested_change) <= 4000), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), resolved_at timestamptz);
create table public.zoom_feedback_status_history (id bigint generated always as identity primary key, feedback_id uuid not null references public.zoom_feedback_reports(id) on delete cascade, previous_status text, new_status text not null, changed_by uuid not null references public.zoom_profiles(id) on delete cascade, created_at timestamptz not null default now());
create table private.zoom_admin_notifications (id bigint generated always as identity primary key, type text not null, subject_user_id uuid references public.zoom_profiles(id) on delete cascade, is_read boolean not null default false, created_at timestamptz not null default now());
create index zoom_events_user_time_idx on public.zoom_usage_events(user_id,created_at); create index zoom_events_type_time_idx on public.zoom_usage_events(event_type,created_at); create index zoom_presence_heartbeat_idx on public.zoom_presence(last_heartbeat);
alter table public.zoom_usage_events enable row level security; alter table public.zoom_usage_sessions enable row level security; alter table public.zoom_presence enable row level security; alter table public.zoom_feedback_reports enable row level security; alter table public.zoom_feedback_status_history enable row level security;
create policy "own event insert" on public.zoom_usage_events for insert to authenticated with check(auth.uid()=user_id and private.zoom_has_valid_access()); create policy "own or JA events" on public.zoom_usage_events for select to authenticated using((auth.uid()=user_id and private.zoom_has_valid_access()) or private.zoom_is_creator_admin());
create policy "own or JA feedback read" on public.zoom_feedback_reports for select to authenticated using((auth.uid()=reporter_user_id and private.zoom_has_valid_access()) or private.zoom_is_creator_admin()); create policy "own feedback insert" on public.zoom_feedback_reports for insert to authenticated with check(auth.uid()=reporter_user_id and private.zoom_has_valid_access()); create policy "JA feedback update" on public.zoom_feedback_reports for update to authenticated using(private.zoom_is_creator_admin()) with check(private.zoom_is_creator_admin());
create policy "own or JA sessions" on public.zoom_usage_sessions for select to authenticated using((auth.uid()=user_id and private.zoom_has_valid_access()) or private.zoom_is_creator_admin());
create policy "own session insert" on public.zoom_usage_sessions for insert to authenticated with check(auth.uid()=user_id and private.zoom_has_valid_access());
create policy "own or JA presence" on public.zoom_presence for select to authenticated using((auth.uid()=user_id and private.zoom_has_valid_access()) or private.zoom_is_creator_admin());
create policy "own presence update" on public.zoom_presence for update to authenticated using(auth.uid()=user_id and private.zoom_has_valid_access()) with check(auth.uid()=user_id and private.zoom_has_valid_access());
create policy "own presence insert" on public.zoom_presence for insert to authenticated with check(auth.uid()=user_id and private.zoom_has_valid_access());
create policy "feedback history read" on public.zoom_feedback_status_history for select to authenticated using(private.zoom_is_creator_admin());
create policy "feedback history insert" on public.zoom_feedback_status_history for insert to authenticated with check(private.zoom_is_creator_admin() and changed_by=auth.uid());
grant select, insert, update on public.zoom_profiles, public.zoom_agent_slots, public.zoom_usage_events, public.zoom_usage_sessions, public.zoom_presence, public.zoom_feedback_reports, public.zoom_feedback_status_history to authenticated;
grant usage, select on all sequences in schema public to authenticated;
